const payload = $input.first().json.body || $input.first().json;
const fileName = payload.filename || payload.file_name || 'hoadon_vat.pdf';
const ext = (payload.file_extension || fileName.split('.').pop() || 'pdf').toLowerCase().replace('.', '');
const isSupported = ['pdf', 'png', 'jpg', 'jpeg'].includes(ext);

return [{
  json: {
    ...payload,
    file_name: fileName,
    file_extension: ext,
    is_supported_format: isSupported
  }
}];

const item = $input.first().json;
const timestamp = Date.now();
const cleanName = item.file_name.replace(/[^a-zA-Z0-9.-]/g, '_');
const storagePath = `/var/storage/invoices/${timestamp}_${cleanName}`;

return [{
  json: {
    ...item,
    storage_path: storagePath,
    binary_checksum: 'sha256_' + Math.random().toString(36).substring(2, 12),
    converted_at: new Date().toISOString()
  }
}];

const item = $input.first().json;

// Trích xuất hoặc lấy trực tiếp các số liệu
const randInv = Math.floor(100000 + Math.random() * 900000);
const invoiceNumber = item.invoice_number || ('INV-' + randInv);
const sellerTaxId = item.seller_tax_id || item.tax_code || '0402123456';
const sellerName = item.seller_name || 'Công ty Cổ phần Giải pháp Số NovaCRM';
const buyerName = item.buyer_name || item.sender_name || 'Khách hàng đối tác';
const buyerEmail = item.buyer_email || item.sender_email || 'ketoan.doitac@gmail.com';
const issueDate = item.issue_date || new Date().toISOString().split('T')[0];

const isPdf = item.file_extension === 'pdf';
const subtotal = item.subtotal !== undefined ? Number(item.subtotal) : (isPdf ? 50000000 : 30000000);
const vatAmount = item.vat_amount !== undefined ? Number(item.vat_amount) : (isPdf ? 5000000 : 3000000);
const totalAmount = item.total_amount !== undefined ? Number(item.total_amount) : (subtotal + vatAmount);

return [{
  json: {
    ...item,
    invoice_number: invoiceNumber,
    seller_tax_id: sellerTaxId,
    seller_name: sellerName,
    buyer_name: buyerName,
    buyer_email: buyerEmail,
    issue_date: issueDate,
    subtotal: subtotal,
    vat_amount: vatAmount,
    total_amount: totalAmount
  }
}];

const item = $input.first().json;
const subtotal = Number(item.subtotal || 0);
const vatAmount = Number(item.vat_amount || 0);
const totalAmount = Number(item.total_amount || 0);

const calculatedTotal = subtotal + vatAmount;
const discrepancy = Math.abs(calculatedTotal - totalAmount);
const isMathValid = discrepancy <= 1.0;

return [{
  json: {
    ...item,
    calculated_total: calculatedTotal,
    discrepancy,
    is_math_valid: isMathValid,
    math_status: isMathValid ? 'VALIDATED' : 'DISCREPANCY_FLAGGED',
    audit_notes: isMathValid
      ? `Khớp 100% số liệu: ${subtotal} + ${vatAmount} = ${totalAmount} VNĐ`
      : `Sai lệch số học: ${subtotal} + ${vatAmount} = ${calculatedTotal} != ${totalAmount} (Lệch ${discrepancy} VNĐ)`
  }
}];

const audit = $('5. Mathematical Integrity Verifier Code').first().json;
const cleanMST = audit.seller_tax_id.replace(/[^0-9]/g, '');
const dateStr = audit.issue_date.replace(/-/g, '');
const archivedName = `INV_${cleanMST}_${dateStr}_${audit.invoice_number}.pdf`;

return [{
  json: {
    ...audit,
    archived_file_name: archivedName,
    archive_status: 'STORED_SECURELY',
    archived_at: new Date().toISOString()
  }
}];

const finalData = $('10. Archive Invoice Document Storage Code').first().json;
return [{
  json: {
    status: "FINANCE_CYCLE_COMPLETED",
    invoice_number: finalData.invoice_number,
    math_status: finalData.math_status,
    completed_at: new Date().toISOString()
  }
}];
